from __future__ import annotations

import argparse
import json
import re
import shutil
import subprocess
import sys
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(
        description="Filters and uploads node_modules to Google Cloud Storage and updates DEPS"
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help="Actually upload and update DEPS (defaults to dry-run)",
    )
    args = parser.parse_args()

    src_dir = Path(__file__).resolve().parent.parent
    node_modules_path = src_dir / "node_modules"
    deps_file_path = src_dir / "DEPS"
    exclude_file_path = Path(__file__).resolve().parent / "npm_exclude.txt"

    if not node_modules_path.exists():
        print(
            f"Error: node_modules directory not found at {node_modules_path}",
            file=sys.stderr,
        )
        print(
            "Please make sure node_modules is populated (e.g. via gclient sync) before running this script.",
            file=sys.stderr,
        )
        sys.exit(1)

    print("Filtering node_modules...")
    filtered_path = src_dir / "node_modules_filtered"
    if filtered_path.exists():
        shutil.rmtree(filtered_path)

    rsync_cmd = [
        "rsync",
        "-c",
        "--delete",
        "-rl",
        "-q",
        f"--exclude-from={exclude_file_path}",
        "--prune-empty-dirs",
        "node_modules/",
        "node_modules_filtered/",
    ]
    subprocess.run(rsync_cmd, cwd=src_dir, check=True)
    shutil.rmtree(node_modules_path)
    filtered_path.rename(node_modules_path)

    if args.force:
        print("Uploading node_modules to GCS... (This might take a while)")
    else:
        print("Dry run mode. Pass --force to actually upload.")

    upload_script = (
        src_dir
        / "../../third_party/depot_tools/upload_to_google_storage_first_class.py"
    ).resolve()
    upload_cmd = [
        "vpython3",
        str(upload_script),
        "--bucket=chromium-nodejs",
        "--prefix=chromium-bidi",
        ".",
    ]
    if not args.force:
        upload_cmd.append("--dry-run")

    result = subprocess.run(
        upload_cmd, cwd=node_modules_path, capture_output=True, text=True
    )
    if result.returncode != 0:
        if not args.force:
            print(
                "Dry-run check failed. This usually means the node_modules archive does not exist on Google Storage yet."
            )
            print("Pass --force to actually upload it and update DEPS.")
            sys.exit(0)
        print("Upload failed:", file=sys.stderr)
        print(result.stdout, file=sys.stderr)
        print(result.stderr, file=sys.stderr)
        sys.exit(1)

    print(result.stdout)
    json_match = re.search(r"\{[\s\S]*\}", result.stdout)
    if not json_match:
        print("Could not find JSON output from upload script.", file=sys.stderr)
        print(f"Output was: {result.stdout}", file=sys.stderr)
        sys.exit(1)

    data = json.loads(json_match.group(0))
    obj = data["path"]["objects"][0]
    object_info = f"{obj['object_name']},{obj['sha256sum']},{obj['size_bytes']},{obj['generation']}"

    setdep_cmd = [
        "gclient",
        "setdep",
        "-r",
        f"node_modules@{object_info}",
        f"--deps-file={deps_file_path}",
    ]

    if args.force:
        print("Updating DEPS file...")
        subprocess.run(setdep_cmd, cwd=src_dir, check=True)
    else:
        print("Dry run: would have updated DEPS file using command:")
        print(" ".join(setdep_cmd))

    print("Done!")


if __name__ == "__main__":
    main()
